 if(page==='presentation'){$('#showPresentationSummary').onclick=()=>{state.presentation=true;document.body.classList.add('presentation-mode');openModal('Ringkasan Presentasi',`<div class="hero" style="min-height:0;padding:24px"><div><div class="eyebrow">HASIL KELOMPOK</div><h1 style="font-size:25px">${esc(state.group)} · CODEMART</h1><p>Saldo: ${rupiah(state.balance)} · Total belanja Dina: ${rupiah(226500)}</p></div></div><div class="terminal" style="margin-top:15px"><div class="terminal-head">EKSPRESI DAN HASIL</div><div class="terminal-body">subtotal = (85000 * 2) + (45000 * 1) → 215000\npajak = subtotal * 10 / 100 → 21500\ntotal = subtotal + pajak + 10000 - 20000 → 226500\ncukup = saldo >= total → ${state.balance>=226500?'true':'false'}</div></div><div class="notice ${state.balance>=226500?'success':'error'}">${state.balance>=226500?'Keputusan: saldo cukup.':'Keputusan: saldo tidak cukup.'} Operator >= menguji apakah saldo lebih besar dari atau sama dengan total.</div><p class="muted small">Ingat untuk menyampaikan alasan dan membandingkan hasil web dengan prediksi kelompok.</p><button class="btn btn-primary" id="closePresentationModal">Kembali ke halaman</button>`);$('#closePresentationModal').onclick=()=>{$('#modalBackdrop').hidden=true;};};$('#savePresentationReason').onclick=()=>{state.reflections.presentationReason=$('#presentationReason').value;save();toast('Alasan disimpan.')}}
