function normalize(v){return String(v).toLowerCase().replace(/[\s.,]/g,'').replace(/rp/g,'')}
function show(sel,msg,type='neutral'){let el=$(sel);if(el)el.innerHTML=`<div class="feedback ${type==='good'?'good':type==='bad'?'bad':'neutral'}">${esc(msg)}</div>`}
function compare(a,op,b){return op==='>'?a>b:op==='<'?a<b:op==='>='?a>=b:op==='<='?a<=b:op==='=='?a===b:a!==b}
function relationExplain(op){return ({'>':'memeriksa nilai kiri lebih besar dari kanan.','<':'memeriksa nilai kiri lebih kecil dari kanan.','>=':'memeriksa nilai kiri lebih besar atau sama dengan kanan.','<=':'memeriksa nilai kiri lebih kecil atau sama dengan kanan.','==':'memeriksa kesamaan dua nilai.','!=':'memeriksa apakah dua nilai berbeda.'})[op]}
function explainExpression(src,val){if(src.includes('10000 + 5000 * 2'))return 'Perkalian 5000 * 2 dikerjakan lebih dahulu, lalu hasilnya ditambah 10000.';if(src.includes('(10000 + 5000) * 2'))return 'Penjumlahan dalam tanda kurung dikerjakan dahulu, lalu hasilnya dikali 2.';if(src.includes('%'))return 'Operator % menghasilkan sisa pembagian.';if(src.includes('subtotal ='))return 'Perkalian dikerjakan sebelum penjumlahan.';if(src.includes('pajak ='))return 'Perkalian dan pembagian memiliki prioritas yang sama dan dikerjakan dari kiri ke kanan.';return typeof val==='boolean'?'Hasil perbandingan berupa true atau false.':'Perhatikan prioritas operator dan tanda kurung.'}
function togglePresentation(){state.presentation=!state.presentation;document.body.classList.toggle('presentation-mode',state.presentation);toast(state.presentation?'Mode presentasi aktif. Tekan tombol layar penuh lagi untuk kembali.':'Mode presentasi ditutup.');if(state.presentation&&state.page!=='presentation')go('presentation')}
function openModal(title,html){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;$('#modalBackdrop').hidden=false}
